// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/archive.ts`. Edit the source and run `just generate`.
// `dotclaude-spec archive <id> [--json]`: merges the requirements of an `accepted` change into `specs/` and moves the change to `archive/`.
// Each `requirements/<capability>.md` adds its requirement sections to `specs/<capability>.md`.
// A trivial change adds its `## Requirements` section to `specs/<id>.md`.
// When one requirement has an ID that its spec has already, nothing changes.

import path from "node:path";
import { ARCHIVE_DIR, SPECS_DIR } from "../../../kernel/paths.ts";
import {
  afterTitle,
  mergeRequirements,
  requirementsSection,
} from "../domain/capability.ts";
import { gateArchive } from "../domain/change-gates.ts";
import { CHANGE_ID } from "../limits.ts";
import { SPEC } from "../templates/files.ts";
import { parseArgs } from "./args.ts";
import { changeDir, readChange } from "./files.ts";
import { dateOf, type Run } from "./run.ts";
import {
  changeState,
  moveChange,
  printMoved,
  refusedInWorktree,
  stop,
  usage,
} from "./transition.ts";

const USAGE = "Usage: dotclaude-spec archive <id> [--json]";

/** The requirement sections of the change `id`, one entry for each capability. */
const bodies = async (run: Run, id: string): Promise<Map<string, string>> => {
  const found = new Map<string, string>();
  const dir = changeDir(id);
  const names = await run.store.markdown(path.posix.join(dir, "requirements"));
  for (const name of names) {
    const body = await run.store.files.read(
      path.posix.join(dir, "requirements", name),
    );
    found.set(name.replace(/\.md$/, ""), afterTitle(body ?? ""));
  }
  if (found.size === 0) {
    const section = requirementsSection(
      (await readChange(run.store, id))?.text ?? "",
    );
    if (section !== "") found.set(id, section);
  }
  return found;
};

export const archiveCommand = async (
  run: Run,
  args: string[],
): Promise<number> => {
  const parsed = parseArgs(args);
  if (typeof parsed === "string") return usage(run, parsed);
  const [id, extra] = parsed.words;
  if (!id || extra !== undefined) return usage(run, USAGE);
  if (!CHANGE_ID.test(id))
    return usage(run, `The id \`${id}\` is not a change id.`);
  if (refusedInWorktree(run, "archives a change")) return 1;
  const events = await run.store.events(id);
  if (events === null) return stop(run, `The change \`${id}\` does not exist.`);
  const gate = gateArchive(changeState(events));
  if (!gate.ok) return stop(run, gate.reason);
  const target = path.posix.join(ARCHIVE_DIR, `${dateOf(run.clock)}-${id}`);
  if (run.store.exists(target))
    return stop(run, `\`${target}\` exists already.`);
  try {
    run.store.makeDir(ARCHIVE_DIR);
  } catch {
    return stop(run, `\`${ARCHIVE_DIR}\` is not a folder.`);
  }
  const texts = new Map<string, string>();
  const problems: string[] = [];
  for (const [capability, body] of await bodies(run, id)) {
    const file = path.posix.join(SPECS_DIR, `${capability}.md`);
    const merged = mergeRequirements(
      await run.store.files.read(file),
      SPEC.replaceAll("<capability>", capability),
      body,
    );
    if ("errors" in merged)
      problems.push(...merged.errors.map((e) => `${file}: ${e}`));
    else texts.set(file, merged.text);
  }
  if (problems.length > 0) {
    for (const line of problems) run.io.error(line);
    return stop(run, `Nothing changed: ${problems.length} problem(s).`);
  }
  for (const [file, text] of texts) await run.store.write(file, text);
  const moved = await moveChange(run, id, "archived");
  run.store.move(changeDir(id), target);
  printMoved(
    run,
    "archive",
    { ...moved, specs: [...texts.keys()] } as typeof moved,
    parsed.json,
  );
  return 0;
};
